const days = 7;
const cutoff = Date.now() - days * 86400000;
const stars = {ONE:1,TWO:2,THREE:3,FOUR:4,FIVE:5};
const reviews = ($input.first().json.reviews || []).filter(r => !r.reviewReply && new Date(r.updateTime).getTime() >= cutoff);
const draft = (r) => {
  const n = stars[r.starRating] || 0;
  const first = ((r.reviewer||{}).displayName || 'there').split(' ')[0];
  if (!r.comment) return `Thanks for the rating, ${first}! If there is anything we can do better, we would love to hear it.`;
  if (n >= 4) return `Thanks so much, ${first}! We are delighted you had a great experience.`;
  if (n === 3) return `Thanks for the feedback, ${first}. We would love to know how we can earn 5 stars next time.`;
  return `Hi ${first}, we are sorry this fell short. Please contact us directly so we can put it right.`;
};
const lines = reviews.map(r => `${stars[r.starRating]||'?'} stars - ${(r.reviewer||{}).displayName||'Anonymous'}: ${r.comment||'(no text)'}\n  DRAFT: ${draft(r)}\n  APPROVE: python -m gbp_mcp.approve reply --review-id ${r.name} --text "${draft(r).replace(/"/g,'\\"')}"`);
return [{json: {count: reviews.length, digest: lines.join('\n\n') || 'No unanswered reviews this week.'}}];

